def keep_existing_access(apps, schema_editor):
    """Before this change an assignment meant "may see the data". Keep that: one record per
    gateway stays connected (with a connection period); any extras become history."""
    from django.utils import timezone

    Assignment = apps.get_model("plants", "GatewayAssignment")
    Period = apps.get_model("plants", "ConnectionPeriod")
    seen = set()
    for a in Assignment.objects.order_by("assigned_at", "pk"):
        if a.gateway_id in seen:
            a.status, a.disconnected_at = "disconnected", timezone.now()
        else:
            seen.add(a.gateway_id)
            a.status, a.connected_at = "connected", a.assigned_at
            Period.objects.create(assignment=a, start=a.assigned_at)
        a.save()


